#include "FrontierWorldGame.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <format>

using namespace Aevrynd;
using namespace FrontierWorldRules;
namespace {
constexpr uint32_t WorldLayer=1,BuildingLayer=2,ActorLayer=4;
constexpr Color Grass{.16f,.34f,.17f,1},DarkGrass{.08f,.22f,.12f,1},Wood{.38f,.19f,.08f,1},Stone{.38f,.42f,.43f,1},Leaf{.08f,.29f,.12f,1},Cyan{.18f,.9f,.82f,1},Gold{1.f,.72f,.22f,1},Ink{.78f,.9f,.88f,1},Coral{.92f,.22f,.14f,1};
}

void FrontierWorldGame::OnStart(Engine& engine){boxMesh_=engine.CreateMeshResource3D(Mesh3D::CreateUnitBox());pyramidMesh_=engine.CreateMeshResource3D(Mesh3D::CreateUnitPyramid());scene_.SetBoxMesh(boxMesh_);collisionWorld_.CreateBox({{{0,-.5f,0},{48,.5f,48}},WorldLayer,CollisionLayerAll3D,0,false});controller_.Reset({0,0,-8});swingSound_=engine.Audio().CreateSound(GenerateTone(180,.1f,.18f));buildSound_=engine.Audio().CreateSound(GenerateTone(620,.12f,.14f));PopulateWorld();if(engine.DLSSOn())engine.ToggleDLSS();}
void FrontierWorldGame::OnStop(Engine& engine){scene_.SetBoxMesh({});engine.DestroyMesh3D(boxMesh_.handle);engine.DestroyMesh3D(pyramidMesh_.handle);engine.Audio().DestroySound(swingSound_);engine.Audio().DestroySound(buildSound_);boxMesh_=pyramidMesh_={};}

void FrontierWorldGame::PopulateWorld(){monsters_={{{0,0,-3},55,55,2.7f,0,MonsterKind::Wolf,true},{{-8,0,4},55,55,2.5f,0,MonsterKind::Wolf,true},{{10,0,10},130,130,1.35f,0,MonsterKind::Golem,true},{{-14,0,-10},130,130,1.25f,0,MonsterKind::Golem,true}};}

bool FrontierWorldGame::Build(BuildingKind kind,Vec3 position,float yaw){++buildAttempts_;const ResourceCost cost=Cost(kind);if(!CanAfford(wood_,stone_,kind))return false;position={std::round(position.x/2.5f)*2.5f,position.y,std::round(position.z/2.5f)*2.5f};Vec3 size=kind==BuildingKind::Foundation?Vec3{5,.4f,5}:kind==BuildingKind::Wall?Vec3{5,3,.35f}:Vec3{5.8f,.55f,5.8f};if(std::abs(std::sin(yaw))>.7f)std::swap(size.x,size.z);const Vec3 center=position+Vec3{0,size.y*.5f,0};if(collisionWorld_.OverlapsBox(center,size*.35f,{BuildingLayer,ActorLayer,false}))return false;const ColliderHandle3D collider=collisionWorld_.CreateBox({{center,size*.5f},BuildingLayer,CollisionLayerAll3D,buildings_.size()+1,false});buildings_.push_back({kind,position,yaw,collider});wood_-=cost.wood;stone_-=cost.stone;return true;}

void FrontierWorldGame::Attack(){if(attackCooldown_>0)return;attackCooldown_=.48f;++attacks_;for(Monster& monster:monsters_){if(!monster.alive||!CanMeleeHit(controller_.Position()+Vec3{0,1,0},yaw_,monster.position+Vec3{0,.7f,0}))continue;monster.health-=24.f+level_*6.f;++hits_;if(monster.health<=0){monster.alive=false;++kills_;experience_+=monster.kind==MonsterKind::Golem?70:35;while(experience_>=ExperienceForLevel(level_)){experience_-=ExperienceForLevel(level_);++level_;health_=(std::min)(100,health_+25);}}}}

void FrontierWorldGame::UpdateMonsters(float deltaTime){for(Monster& monster:monsters_){if(!monster.alive)continue;monster.attackCooldown=(std::max)(0.f,monster.attackCooldown-deltaTime);const Vec3 delta=controller_.Position()-monster.position;const float distance=Length(Vec3{delta.x,0,delta.z});if(distance<1.55f){if(monster.attackCooldown<=0){health_=(std::max)(0,health_-(monster.kind==MonsterKind::Golem?14:7));monster.attackCooldown=1.1f;}}else if(distance<24.f){const Vec3 direction=Normalize(Vec3{delta.x,0,delta.z});const Vec3 proposed=monster.position+direction*(monster.speed*deltaTime);if(!collisionWorld_.OverlapsBox(proposed+Vec3{0,.65f,0},{.45f,.65f,.45f},{BuildingLayer,ActorLayer,false}))monster.position=proposed;}}if(health_<=0){health_=100;controller_.Reset({0,0,-8});}}

void FrontierWorldGame::OnUpdate(Engine& engine,float deltaTime){Input& input=engine.GetInput();if(input.Pressed(VK_ESCAPE))engine.Quit();if(input.Pressed(VK_F4))automatic_=!automatic_;if(input.Pressed(VK_F1)){firstPerson_=true;automatic_=false;}if(input.Pressed(VK_F2)){firstPerson_=false;automatic_=false;}if(input.Pressed('1'))selectedBuilding_=BuildingKind::Foundation;if(input.Pressed('2'))selectedBuilding_=BuildingKind::Wall;if(input.Pressed('3'))selectedBuilding_=BuildingKind::Roof;attackCooldown_=(std::max)(0.f,attackCooldown_-deltaTime);automaticClock_+=deltaTime;CharacterControl3D control{};bool attack=false,build=false;if(automatic_){firstPerson_=int(automaticClock_/6.f)%2==1;const int phase=int(automaticClock_/3.f)%4;const Vec3 directions[4]={{0,0,1},{1,0,0},{0,0,-1},{-1,0,0}};control.movement=directions[phase];yaw_=std::atan2(control.movement.x,control.movement.z);attack=true;static constexpr std::array<Vec3,6> positions={Vec3{6,0,6},Vec3{6,.4f,3.5f},Vec3{6,.4f,8.5f},Vec3{3.5f,.4f,6},Vec3{8.5f,.4f,6},Vec3{6,3.4f,6}};const std::size_t next=buildings_.size();if(next<positions.size()&&automaticClock_>1.f+float(next)*1.2f){const BuildingKind kind=next==0?BuildingKind::Foundation:next==5?BuildingKind::Roof:BuildingKind::Wall;const float rotation=next==3||next==4?1.5707963f:0;build=Build(kind,positions[next],rotation);}}else{yaw_+=(float(input.Down(VK_RIGHT))-float(input.Down(VK_LEFT))-input.MouseDelta().x*.02f)*deltaTime*2.4f;pitch_=Clamp(pitch_+(float(input.Down(VK_UP))-float(input.Down(VK_DOWN)))*deltaTime*1.5f,-.35f,.7f);const Vec3 forward{std::sin(yaw_),0,std::cos(yaw_)},right{std::cos(yaw_),0,-std::sin(yaw_)};control.movement=forward*(float(input.Down('W'))-float(input.Down('S')))+right*(float(input.Down('D'))-float(input.Down('A')));control.jump=input.Pressed(VK_RETURN);attack=input.MousePressed()||input.Pressed('F');if(input.Pressed('B'))build=Build(selectedBuilding_,controller_.Position()+forward*5.f,selectedBuilding_==BuildingKind::Wall?yaw_:0);}controller_.Step(control,collisionWorld_,deltaTime,WorldLayer|BuildingLayer,ActorLayer);if(attack){const uint64_t before=attacks_;Attack();if(attacks_>before)engine.Audio().Play(swingSound_);}if(build)engine.Audio().Play(buildSound_);UpdateMonsters(deltaTime);const auto physics=collisionWorld_.Stats();engine.SetTitle(std::format(L"Aevrynd Frontier World | {} | HP {} LV {} XP {} | WOOD {} STONE {} | BUILD {} | MONSTERS {} KILLS {} | SWING {}/{} | CHUNKS {} | PHYS Q{}",firstPerson_?L"FIRST PERSON":L"THIRD PERSON",health_,level_,experience_,wood_,stone_,buildings_.size(),std::count_if(monsters_.begin(),monsters_.end(),[](const Monster& value){return value.alive;}),kills_,hits_,attacks_,loadedChunks_,physics.queries));}

void FrontierWorldGame::AddHumanoid(Vec3 position,float yaw,bool armed){scene_.Mesh(boxMesh_,{position+Vec3{0,1.15f,0},{0,yaw,0},{.7f,1.05f,.38f}},{{.16f,.42f,.58f,1}});scene_.Mesh(boxMesh_,{position+Vec3{0,1.88f,0},{0,yaw,0},{.46f,.46f,.46f}},{{.72f,.53f,.38f,1}});scene_.Mesh(boxMesh_,{position+Vec3{-.2f,.38f,0},{0,yaw,0},{.22f,.75f,.25f}},{{.1f,.16f,.2f,1}});scene_.Mesh(boxMesh_,{position+Vec3{.2f,.38f,0},{0,yaw,0},{.22f,.75f,.25f}},{{.1f,.16f,.2f,1}});if(armed){const Vec3 right{std::cos(yaw),0,-std::sin(yaw)},forward{std::sin(yaw),0,std::cos(yaw)};scene_.Mesh(boxMesh_,{position+Vec3{0,1.15f,0}+right*.58f+forward*.3f,{.18f,yaw,0},{.08f,.1f,1.5f}},{{.72f,.78f,.8f,1}});}}
void FrontierWorldGame::AddMonster(const Monster& monster){if(!monster.alive)return;if(monster.kind==MonsterKind::Wolf){scene_.Mesh(boxMesh_,{monster.position+Vec3{0,.62f,0},{0,0,0},{1.15f,.62f,.48f}},{{.25f,.27f,.3f,1}});scene_.Mesh(boxMesh_,{monster.position+Vec3{0,.78f,.58f},{0,0,0},{.55f,.48f,.55f}},{{.31f,.32f,.34f,1}});for(float x:{-.4f,.4f})for(float z:{-.32f,.32f})scene_.Mesh(boxMesh_,{monster.position+Vec3{x,.25f,z},{0,0,0},{.16f,.5f,.16f}},{{.16f,.16f,.18f,1}});}else{scene_.Mesh(boxMesh_,{monster.position+Vec3{0,1.15f,0},{0,0,0},{1.25f,1.65f,.8f}},{{.34f,.38f,.4f,1}});scene_.Mesh(boxMesh_,{monster.position+Vec3{0,2.2f,0},{0,0,0},{.72f,.65f,.7f}},{{.42f,.46f,.45f,1}});for(float x:{-.85f,.85f})scene_.Mesh(boxMesh_,{monster.position+Vec3{x,1.2f,0},{0,0,0},{.4f,1.35f,.42f}},{{.29f,.32f,.34f,1}});}scene_.Box(monster.position+Vec3{0,2.8f,0},{1.8f,.12f,.12f},{.12f,.03f,.02f,1});scene_.Box(monster.position+Vec3{-.9f+1.8f*(monster.health/monster.maximumHealth)*.5f,2.8f,-.01f},{1.8f*(monster.health/monster.maximumHealth),.13f,.13f},Coral);}

void FrontierWorldGame::AddEnvironment(){scene_.Box({0,-.5f,0},{96,1,96},Grass);scene_.Box({35,-.25f,0},{20,.5f,96},{.05f,.22f,.3f,.92f});for(int line=-40;line<=40;line+=8){scene_.Line({float(line),.01f,-40},{float(line),.01f,40},.8f,{.12f,.3f,.14f,.45f});scene_.Line({-40,.01f,float(line)},{40,.01f,float(line)},.8f,{.12f,.3f,.14f,.45f});}for(int index=0;index<26;++index){const float x=float((index*17)%61-30),z=float((index*29)%67-33);if(std::abs(x)<10&&std::abs(z)<12)continue;scene_.Mesh(boxMesh_,{{x,1.25f,z},{0,float(index),0},{.5f,2.5f,.5f}},{{.28f,.12f,.045f,1}});scene_.Mesh(pyramidMesh_,{{x,3.1f,z},{0,float(index),0},{2.8f,3.8f,2.8f}},{{.04f+.01f*(index%4),.24f+.02f*(index%3),.08f,1}});}for(int index=0;index<18;++index){const float x=float((index*23)%55-27),z=float((index*13)%51-25);scene_.Mesh(boxMesh_,{{x,.35f,z},{float(index)*.1f,float(index)*.3f,0},{.7f+float(index%3)*.35f,.55f,.8f}},{{.3f,.32f,.31f,1}});}for(const Building& building:buildings_){if(building.kind==BuildingKind::Foundation)scene_.Mesh(boxMesh_,{building.position+Vec3{0,.2f,0},{0,building.yaw,0},{5,.4f,5}},{{.42f,.39f,.31f,1}});else if(building.kind==BuildingKind::Wall)scene_.Mesh(boxMesh_,{building.position+Vec3{0,1.5f,0},{0,building.yaw,0},{5,3,.35f}},{{.46f,.25f,.1f,1}});else{scene_.Mesh(boxMesh_,{building.position+Vec3{0,.15f,0},{0,0,.43f},{5.8f,.35f,3.2f}},{{.28f,.08f,.035f,1}});scene_.Mesh(boxMesh_,{building.position+Vec3{0,.15f,0},{0,0,-.43f},{5.8f,.35f,3.2f}},{{.32f,.095f,.04f,1}});}}}

void FrontierWorldGame::OnRender(Engine& engine,float){scene_.Clear();AddEnvironment();const Vec3 feet=controller_.Position(),focus=feet+Vec3{0,1.3f,0};if(firstPerson_)camera_=MakeFirstPersonCamera(feet+Vec3{0,1.68f,0},yaw_,pitch_);else{const Camera3D desired=MakeThirdPersonCamera(focus,yaw_,.25f,7.8f);camera_=ConstrainThirdPersonCamera(desired,focus,collisionWorld_,.2f,WorldLayer|BuildingLayer,ActorLayer);AddHumanoid(feet,yaw_,true);}for(const Monster& monster:monsters_)AddMonster(monster);DrawList& draw=engine.Draw();const float daylight=.55f+.35f*std::sin(engine.Time()*.035f);draw.SetDirectionalLight({{.45f,-1,.3f},.22f,{1.f,.86f,.68f,1},daylight});scene_.Submit(draw,camera_,{1280,720});draw.Quad({640,38},{1280,76},{.015f,.025f,.03f,.94f});draw.Text({24,16},"AEVRYND FRONTIER WORLD",3.2f,Cyan);draw.Text({520,18},std::format("HP {}  LEVEL {}  XP {}  WOOD {}  STONE {}",health_,level_,experience_,wood_,stone_),2.3f,Ink);draw.Text({1070,18},firstPerson_?"FIRST":"THIRD",2.3f,Gold);draw.Line({630,360},{650,360},2,Cyan);draw.Line({640,350},{640,370},2,Cyan);draw.Quad({640,686},{1280,68},{.015f,.025f,.03f,.94f});draw.Text({24,668},std::format("HOUSE {}  MONSTERS {}  KILLS {}  MELEE {}/{}  WORLD CHUNKS {}",buildings_.size(),std::count_if(monsters_.begin(),monsters_.end(),[](const Monster& value){return value.alive;}),kills_,hits_,attacks_,loadedChunks_),2.05f,Ink);draw.Text({930,668},automatic_?"AUTO WORLD TEST":"WASD F B 1 2 3",1.85f,automatic_?Cyan:Gold);}
